INSERT INTO frameworks (idx, slug, name, section, purpose, key_questions, when_to_use, when_not_to_use, inputs_required, outputs, executive_example, consultant_use_case, facilitation_tips) VALUES
  (1, 'identifying-key-segments', 'Identifying Key Segments', 'Knowing Your Business', 'To identify and prioritise the product–market segments that materially contribute to sales and operating profit, forming the foundation for strategy analysis.', 'Where does profit reside in the business? Which product–customer combinations matter most today and in the future?', 'At the very start of strategy formulation, before any market, competitive, or internal analysis.', 'Avoid analysing segments that are immaterial to profit; avoid relying only on product, geography, or customer views in isolation; avoid waiting for perfect data instead of making estimates.', 'Product/service list; customer group definitions; historical sales data; estimated margins or contribution data.', 'Defined product–market segments; prioritised list of key segments; current and forward-looking segment contribution views.', 'Leadership agrees to focus strategy on the few segments generating the majority of operating profit.', 'Segment-level sales and contribution reconstruction to focus downstream analysis on material areas.', 'Force explicit definition of segments as product × customer; challenge overly broad or vague segmentation.')
INSERT INTO frameworks (idx, slug, name, section, purpose, key_questions, when_to_use, when_not_to_use, inputs_required, outputs, executive_example, consultant_use_case, facilitation_tips) VALUES
  (2, 'issue-analysis-minto', 'Issue Analysis (Minto)', 'Knowing Your Business', 'To structure the key strategic questions and sub-questions that must be answered to develop a coherent and complete strategy.', 'What are the critical questions that must be answered to arrive at a winning strategy?', 'Immediately after defining key segments, to guide research and analysis throughout the strategy process.', 'Avoid unstructured brainstorming; avoid jumping to solutions before clarifying the questions; avoid excessively granular question trees.', 'Initial understanding of the business; preliminary hypotheses; strategic objectives or concerns.', 'Structured issue tree or question waterfall guiding analysis and research.', 'Executive team aligns on the few critical strategic questions that need resolution before committing to a direction.', 'Development of a structured issue tree to guide analysis, data collection, and workstream design.', 'Start with one top question; insist on logical completeness and mutual exclusivity of sub-questions.')
INSERT INTO frameworks (idx, slug, name, section, purpose, key_questions, when_to_use, when_not_to_use, inputs_required, outputs, executive_example, consultant_use_case, facilitation_tips) VALUES
  (3, 'the-80-20-principle-pareto', 'The 80/20 Principle (Pareto)', 'Knowing Your Business', 'To focus attention on the minority of factors that drive the majority of outcomes, particularly profits, costs, or issues.', 'Which small number of factors explain most of the results we see?', 'When prioritising segments, issues, customers, products, or cost drivers during early analysis.', 'Avoid treating 80/20 as a law rather than a heuristic; avoid oversimplifying complex situations.', 'Performance data across segments, customers, products, or activities.', 'Ranked list of high-impact contributors; visual concentration charts.', 'Management focuses improvement efforts on the few customers or products driving most profit.', 'Identification of high-impact areas to prioritise analysis and recommendations.', 'Ask participants to identify the “vital few” before discussing the “useful many.”')
INSERT INTO frameworks (idx, slug, name, section, purpose, key_questions, when_to_use, when_not_to_use, inputs_required, outputs, executive_example, consultant_use_case, facilitation_tips) VALUES
  (4, 'the-segmentation-mincer-koch', 'The Segmentation Mincer (Koch)', 'Knowing Your Business', 'To refine and deepen segmentation by repeatedly slicing the business to reveal hidden profit pools.', 'How can we segment the business in different ways to uncover where value is really created?', 'After initial segmentation, when deeper insight into profit drivers is needed.', 'Avoid endless re-segmentation without strategic relevance; avoid segments that cannot be acted upon.', 'Existing segmentation views; financial and operational data; alternative segmentation lenses.', 'Alternative segmentation views highlighting profit concentration or loss areas.', 'Leadership uncovers a previously hidden high-margin niche segment.', 'Iterative segmentation analysis to reveal non-obvious strategic opportunities.', 'Encourage multiple segmentation lenses; stop when insight, not novelty, is achieved.')
INSERT INTO frameworks (idx, slug, name, section, purpose, key_questions, when_to_use, when_not_to_use, inputs_required, outputs, executive_example, consultant_use_case, facilitation_tips) VALUES
  (5, '5c-situation-analysis', '5C Situation Analysis', 'Knowing Your Business', 'To provide a structured overview of the business context by examining Company, Customers, Competitors, Collaborators, and Context.', 'What is the current situation of the business across internal and external dimensions?', 'As an early-stage diagnostic to build a shared understanding of the business environment.', 'Avoid superficial checklist completion; avoid using it as a substitute for deeper analysis tools.', 'Internal performance information; customer insights; competitor data; partner information; macro context data.', 'High-level situational snapshot covering the five dimensions.', 'Executives align on a shared view of the company’s current situation.', 'Rapid structured diagnosis to orient the strategy team and frame deeper analyses.', 'Assign one “C” per group to ensure balanced discussion and coverage.')
INSERT INTO frameworks (idx, slug, name, section, purpose, key_questions, when_to_use, when_not_to_use, inputs_required, outputs, executive_example, consultant_use_case, facilitation_tips) VALUES
  (6, 'swot-analysis-andrews', 'SWOT Analysis (Andrews)', 'Knowing Your Business', 'To summarise internal strengths and weaknesses alongside external opportunities and threats affecting the business.', 'What internal and external factors could materially influence strategic success?', 'After initial internal and external analysis, as a synthesis tool.', 'Avoid generic lists; avoid mixing internal and external factors; avoid treating SWOT as a strategy itself.', 'Internal capability assessments; market and competitive insights; environmental analysis.', 'Structured SWOT matrix highlighting key strategic factors.', 'Leadership reviews a concise snapshot of key strengths, weaknesses, opportunities, and threats.', 'Synthesis of analysis outputs into a single, communicable diagnostic view.', 'Push for specificity and evidence behind each item; limit the list to what truly matters.')
INSERT INTO frameworks (idx, slug, name, section, purpose, key_questions, when_to_use, when_not_to_use, inputs_required, outputs, executive_example, consultant_use_case, facilitation_tips) VALUES
  (7, 'setting-long-term-goals', 'Setting Long-Term Goals', 'Setting Goals and Objectives', 'To define the overarching long-term goals that express what the organisation ultimately aims to achieve.', 'What are we trying to achieve in the long term? What does success look like for this business?', 'Early in the strategy process, after understanding the business and before defining detailed objectives.', 'Avoid vague or contradictory goals; avoid confusing goals with short-term targets or initiatives.', 'Leadership aspirations; ownership expectations; high-level performance ambitions.', 'Clear statement of long-term goals providing direction for the strategy.', 'Board agrees on a small number of long-term goals such as growth, profitability, or sustainability.', 'Facilitation of leadership discussions to articulate and align on long-term ambitions.', 'Encourage debate on trade-offs; ensure goals are explicit and prioritised.')
INSERT INTO frameworks (idx, slug, name, section, purpose, key_questions, when_to_use, when_not_to_use, inputs_required, outputs, executive_example, consultant_use_case, facilitation_tips) VALUES
  (8, 'setting-smart-objectives', 'Setting SMART Objectives', 'Setting Goals and Objectives', 'To translate long-term goals into specific, measurable, achievable, relevant, and time-bound objectives.', 'How can we convert our goals into concrete, trackable objectives?', 'After long-term goals are agreed, to operationalise them into actionable objectives.', 'Avoid objectives that are not measurable; avoid excessive numbers of objectives; avoid setting objectives detached from strategy.', 'Long-term goals; baseline performance data; time horizons.', 'Set of SMART objectives aligned to strategic goals.', 'Executives approve a small number of measurable objectives tied to strategic priorities.', 'Development of objective frameworks linking strategy to performance tracking.', 'Test each objective explicitly against all SMART criteria.')
INSERT INTO frameworks (idx, slug, name, section, purpose, key_questions, when_to_use, when_not_to_use, inputs_required, outputs, executive_example, consultant_use_case, facilitation_tips) VALUES
  (9, 'maximising-shareholder-value', 'Maximising Shareholder Value', 'Setting Goals and Objectives', 'To focus strategy on increasing the value delivered to shareholders over time.', 'How does this strategy create and maximise value for shareholders?', 'When shareholder value creation is a primary goal of the business.', 'Avoid narrow financial focus where other stakeholders dominate; avoid short-termism.', 'Financial performance data; valuation drivers; investment expectations.', 'Clear articulation of value drivers and their link to strategy.', 'Leadership evaluates strategic options based on their impact on shareholder value.', 'Financial modelling and value-driver analysis to assess strategic choices.', 'Separate value drivers from initiatives; keep the discussion focused on value creation logic.')
INSERT INTO frameworks (idx, slug, name, section, purpose, key_questions, when_to_use, when_not_to_use, inputs_required, outputs, executive_example, consultant_use_case, facilitation_tips) VALUES
  (10, 'balancing-stakeholder-interests-corporate-social-responsibility', 'Balancing Stakeholder Interests (Corporate Social Responsibility)', 'Setting Goals and Objectives', 'To ensure that strategy considers and balances the interests of key stakeholders beyond shareholders.', 'Which stakeholders matter, and how should their interests be balanced?', 'When defining objectives that affect employees, customers, communities, and society.', 'Avoid treating CSR as an add-on; avoid vague commitments without strategic relevance.', 'Stakeholder mapping; expectations of key stakeholder groups.', 'Defined stakeholder priorities and their implications for strategy.', 'Executives agree on explicit commitments to key stakeholder groups.', 'Structured stakeholder analysis informing strategic objectives.', 'Ask participants to explicitly prioritise stakeholders rather than listing all equally.')
INSERT INTO frameworks (idx, slug, name, section, purpose, key_questions, when_to_use, when_not_to_use, inputs_required, outputs, executive_example, consultant_use_case, facilitation_tips) VALUES
  (11, 'creating-shared-value-porter-and-kramer', 'Creating Shared Value (Porter and Kramer)', 'Setting Goals and Objectives', 'To identify opportunities where addressing social issues also creates economic value.', 'Where can social and economic value be created simultaneously?', 'When exploring growth or innovation opportunities linked to societal needs.', 'Avoid treating shared value as philanthropy; avoid initiatives without economic logic.', 'Social and environmental context data; business capabilities.', 'Identified shared value opportunities aligned with strategy.', 'Leadership endorses initiatives that deliver both business and societal benefits.', 'Identification and evaluation of shared value initiatives as part of growth strategy.', 'Anchor discussions in both social impact and economic returns.')
INSERT INTO frameworks (idx, slug, name, section, purpose, key_questions, when_to_use, when_not_to_use, inputs_required, outputs, executive_example, consultant_use_case, facilitation_tips) VALUES
  (12, 'economic-value-added-eva', 'Economic Value Added (EVA)', 'Setting Goals and Objectives', 'To measure value creation by assessing returns above the cost of capital.', 'Are we generating returns above our cost of capital?', 'When evaluating performance and investment decisions from a value-creation perspective.', 'Avoid using EVA without understanding capital costs; avoid treating it as the sole performance metric.', 'Financial statements; cost of capital estimates.', 'EVA calculations and performance assessments.', 'Executives assess business units based on value created above capital costs.', 'Financial analysis to support strategic investment decisions.', 'Clarify assumptions behind cost of capital before calculations.')
INSERT INTO frameworks (idx, slug, name, section, purpose, key_questions, when_to_use, when_not_to_use, inputs_required, outputs, executive_example, consultant_use_case, facilitation_tips) VALUES
  (13, 'balanced-scorecard-and-strategy-map-kaplan-and-norton', 'Balanced Scorecard and Strategy Map (Kaplan and Norton)', 'Setting Goals and Objectives', 'To translate strategy into a balanced set of performance measures across multiple perspectives.', 'How do we track strategy execution beyond financial measures?', 'After objectives are defined, to design a comprehensive performance management system.', 'Avoid too many measures; avoid weak causal links between measures and strategy.', 'Strategic objectives; performance indicators; organisational perspectives.', 'Balanced scorecard and strategy map linking objectives and measures.', 'Leadership reviews performance across financial and non-financial dimensions.', 'Design of scorecards and strategy maps to support execution and alignment.', 'Emphasise cause–effect logic between perspectives.')
INSERT INTO frameworks (idx, slug, name, section, purpose, key_questions, when_to_use, when_not_to_use, inputs_required, outputs, executive_example, consultant_use_case, facilitation_tips) VALUES
  (14, 'core-ideology-collins-and-porras', 'Core Ideology (Collins and Porras)', 'Setting Goals and Objectives', 'To articulate the organisation’s core purpose and enduring values.', 'What do we stand for, and why do we exist beyond making money?', 'When clarifying the enduring foundations that guide strategy and behaviour.', 'Avoid confusing ideology with strategy; avoid generic value statements.', 'Leadership beliefs; organisational history and culture.', 'Clearly articulated core purpose and core values.', 'Executives reaffirm the organisation’s purpose and values.', 'Facilitation of discussions to surface and codify core ideology.', 'Distinguish what is enduring from what is changeable.')
INSERT INTO frameworks (idx, slug, name, section, purpose, key_questions, when_to_use, when_not_to_use, inputs_required, outputs, executive_example, consultant_use_case, facilitation_tips) VALUES
  (15, 'obliquity-kay', 'Obliquity (Kay)', 'Setting Goals and Objectives', 'To recognise that complex goals are often best achieved indirectly rather than through direct pursuit.', 'Are there goals that should be pursued indirectly?', 'When direct optimisation risks undermining long-term success.', 'Avoid using obliquity to justify lack of focus; avoid ambiguity in execution.', 'Strategic goals; understanding of system complexity.', 'Reframed goals or approaches recognising indirect paths to success.', 'Leadership accepts that some outcomes emerge indirectly from good strategy.', 'Advising clients on indirect approaches to complex strategic goals.', 'Use examples to illustrate indirect success paths.')
INSERT INTO frameworks (idx, slug, name, section, purpose, key_questions, when_to_use, when_not_to_use, inputs_required, outputs, executive_example, consultant_use_case, facilitation_tips) VALUES
  (16, 'business-as-a-community-handy', 'Business as a Community (Handy)', 'Setting Goals and Objectives', 'To view the organisation as a community with shared purpose rather than purely an economic machine.', 'What obligations does the business have to its members and society?', 'When shaping goals that emphasise meaning, trust, and long-term sustainability.', 'Avoid romanticising the concept; avoid neglecting economic realities.', 'Organisational values; stakeholder expectations.', 'Goals reflecting community and social responsibility.', 'Executives emphasise trust and purpose alongside performance.', 'Integration of community perspective into goal-setting discussions.', 'Encourage reflection on mutual obligations between organisation and people.')
INSERT INTO frameworks (idx, slug, name, section, purpose, key_questions, when_to_use, when_not_to_use, inputs_required, outputs, executive_example, consultant_use_case, facilitation_tips) VALUES
  (17, 'sizing-the-market-and-marketcrafting-evans', 'Sizing the Market and Marketcrafting (Evans)', 'Forecasting Market Demand', 'To estimate the size and growth potential of the market and to define the realistic market opportunity available to the business.', 'How big is the market today and in the future? What share of it is realistically addressable?', 'When assessing growth potential and setting demand-related assumptions for strategy.', 'Avoid relying on top-down market figures without grounding; avoid overestimating addressable demand.', 'Market data; industry reports; customer segmentation; pricing assumptions.', 'Market size estimates (current and forecast); defined addressable market.', 'Leadership reviews market size to validate growth ambitions.', 'Market sizing models to support strategic choices and investment decisions.', 'Clarify assumptions at each step of the market-sizing logic.')
INSERT INTO frameworks (idx, slug, name, section, purpose, key_questions, when_to_use, when_not_to_use, inputs_required, outputs, executive_example, consultant_use_case, facilitation_tips) VALUES
  (18, 'the-hoof-approach-to-demand-forecasting-evans', 'The HOOF Approach to Demand Forecasting (Evans)', 'Forecasting Market Demand', 'To forecast demand by combining historical data, observed trends, opinion, and formal modelling.', 'What is the most realistic forecast of future demand?', 'When building demand forecasts to underpin strategic planning.', 'Avoid over-reliance on a single forecasting method; avoid ignoring judgement and context.', 'Historical sales data; trend information; expert opinions; modelling assumptions.', 'Demand forecasts combining multiple perspectives.', 'Executives review consolidated demand forecasts before approving strategy.', 'Structured demand forecasting integrating quantitative and qualitative inputs.', 'Make each HOOF component explicit and discuss confidence levels.')
INSERT INTO frameworks (idx, slug, name, section, purpose, key_questions, when_to_use, when_not_to_use, inputs_required, outputs, executive_example, consultant_use_case, facilitation_tips) VALUES
  (19, 'income-elasticity-of-demand', 'Income Elasticity of Demand', 'Forecasting Market Demand', 'To assess how sensitive demand is to changes in income levels.', 'How will changes in customer income affect demand for our products or services?', 'When analysing demand drivers in relation to economic conditions.', 'Avoid assuming elasticity is constant across segments; avoid using it in isolation.', 'Historical demand data; income or economic indicators.', 'Estimated income elasticity measures.', 'Leadership considers economic scenarios when planning growth.', 'Economic sensitivity analysis to inform demand assumptions.', 'Link elasticity discussion to specific customer segments.')
INSERT INTO frameworks (idx, slug, name, section, purpose, key_questions, when_to_use, when_not_to_use, inputs_required, outputs, executive_example, consultant_use_case, facilitation_tips) VALUES
  (20, 'the-five-forces-porter', 'The Five Forces (Porter)', 'Gauging Industry Competition', 'To analyse the structural attractiveness of an industry by examining competitive forces shaping profitability.', 'How intense is competition, and what drives industry profitability?', 'When assessing industry structure and profit potential.', 'Avoid static analysis without considering change; avoid confusing competitive intensity with rivalry alone.', 'Industry data; competitor information; supplier and buyer dynamics; substitutes and entry barriers.', 'Five Forces assessment summarising industry attractiveness.', 'Leadership assesses whether the industry can sustain attractive returns.', 'Industry structure analysis to inform positioning and strategic choices.', 'Address each force separately; anchor discussion in evidence.')
INSERT INTO frameworks (idx, slug, name, section, purpose, key_questions, when_to_use, when_not_to_use, inputs_required, outputs, executive_example, consultant_use_case, facilitation_tips) VALUES
  (21, 'assessing-customer-purchasing-criteria', 'Assessing Customer Purchasing Criteria', 'Gauging Industry Competition', 'To identify the factors customers use to choose between competing offerings.', 'What matters most to customers when they make purchasing decisions?', 'When linking customer needs to competitive positioning.', 'Avoid assuming internal priorities equal customer priorities; avoid generic criteria.', 'Customer insights; sales feedback; market research.', 'Ranked list of purchasing criteria by customer segment.', 'Executives align value proposition with key customer buying factors.', 'Customer-driven analysis to refine competitive positioning.', 'Push teams to prioritise criteria, not list everything.')
INSERT INTO frameworks (idx, slug, name, section, purpose, key_questions, when_to_use, when_not_to_use, inputs_required, outputs, executive_example, consultant_use_case, facilitation_tips) VALUES
  (22, 'deriving-key-success-factors', 'Deriving Key Success Factors', 'Gauging Industry Competition', 'To identify the capabilities and attributes required to compete successfully in the industry.', 'What must a firm do well to succeed in this industry?', 'After understanding competition and customer criteria.', 'Avoid confusing key success factors with internal strengths; avoid excessive lists.', 'Industry analysis; customer purchasing criteria; competitor benchmarks.', 'Clear set of industry key success factors.', 'Leadership agrees on what truly differentiates winners from losers.', 'Translation of industry insights into capability requirements.', 'Link each success factor explicitly to customer and competitive drivers.')
INSERT INTO frameworks (idx, slug, name, section, purpose, key_questions, when_to_use, when_not_to_use, inputs_required, outputs, executive_example, consultant_use_case, facilitation_tips) VALUES
  (23, 'weighing-economies-of-scale', 'Weighing Economies of Scale', 'Gauging Industry Competition', 'To assess the impact of scale on cost position and competitiveness.', 'Does size confer a cost advantage in this industry?', 'When analysing cost structures and barriers to entry.', 'Avoid assuming bigger is always cheaper; avoid ignoring minimum efficient scale.', 'Cost data; production volumes; competitor scale information.', 'Assessment of scale effects on costs and competition.', 'Executives evaluate growth or consolidation strategies.', 'Cost-curve analysis to assess scale advantages.', 'Visualise scale effects with simple curves or comparisons.')
INSERT INTO frameworks (idx, slug, name, section, purpose, key_questions, when_to_use, when_not_to_use, inputs_required, outputs, executive_example, consultant_use_case, facilitation_tips) VALUES
  (24, 'corporate-environment-as-a-sixth-force', 'Corporate Environment as a Sixth Force', 'Gauging Industry Competition', 'To assess the influence of governments, regulators, and institutions on industry competition.', 'How do regulation and public policy affect industry dynamics?', 'When operating in regulated or politically influenced industries.', 'Avoid treating regulation as static; avoid ignoring enforcement realities.', 'Regulatory frameworks; policy trends; institutional context.', 'Assessment of regulatory impact on competition.', 'Leadership factors regulatory risk into strategic decisions.', 'Regulatory and institutional analysis within industry assessment.', 'Separate formal rules from informal enforcement practices.')
INSERT INTO frameworks (idx, slug, name, section, purpose, key_questions, when_to_use, when_not_to_use, inputs_required, outputs, executive_example, consultant_use_case, facilitation_tips) VALUES
  (25, 'complements-as-a-sixth-force-brandenburger-and-nalebuff', 'Complements as a Sixth Force (Brandenburger and Nalebuff)', 'Gauging Industry Competition', 'To analyse how complementary products or services affect industry value creation.', 'Which complementary offerings increase the value of our product?', 'When ecosystem effects materially influence demand or value.', 'Avoid ignoring dependencies on complements; avoid assuming complements are always beneficial.', 'Ecosystem mapping; partner information; customer usage patterns.', 'Identification of key complements and their strategic implications.', 'Executives consider partnerships or ecosystem plays.', 'Ecosystem analysis to identify leverage points beyond direct competitors.', 'Map complements visually around the core offering.')
INSERT INTO frameworks (idx, slug, name, section, purpose, key_questions, when_to_use, when_not_to_use, inputs_required, outputs, executive_example, consultant_use_case, facilitation_tips) VALUES
  (26, 'pestel-analysis', 'PESTEL Analysis', 'Gauging Industry Competition', 'To assess the macro-environmental factors shaping industry conditions.', 'What external forces could materially impact the industry?', 'When scanning the broader environment affecting competition.', 'Avoid generic lists; avoid treating PESTEL as predictive rather than exploratory.', 'Political, economic, social, technological, environmental, and legal data.', 'Structured overview of macro-environmental drivers.', 'Leadership discusses external risks and trends affecting the industry.', 'Environmental scanning to inform assumptions and scenarios.', 'Focus discussion on factors with clear strategic relevance.')
INSERT INTO frameworks (idx, slug, name, section, purpose, key_questions, when_to_use, when_not_to_use, inputs_required, outputs, executive_example, consultant_use_case, facilitation_tips) VALUES
  (27, 'rating-competitive-position', 'Rating Competitive Position', 'Tracking Competitive Advantage', 'To assess how the firm currently performs relative to competitors across key success factors.', 'How strong is our competitive position versus competitors today?', 'After identifying industry key success factors and before defining future positioning.', 'Avoid subjective scoring without evidence; avoid averaging away critical weaknesses.', 'Key success factors; competitor benchmarks; internal performance data.', 'Competitive position rating or scorecard.', 'Leadership reviews relative strengths and weaknesses versus key competitors.', 'Structured competitive benchmarking to identify advantage and gaps.', 'Agree on scoring logic and evidence before rating.')
INSERT INTO frameworks (idx, slug, name, section, purpose, key_questions, when_to_use, when_not_to_use, inputs_required, outputs, executive_example, consultant_use_case, facilitation_tips) VALUES
  (28, 'the-resource-and-capability-strengths-importance-matrix-grant', 'The Resource and Capability Strengths/Importance Matrix (Grant)', 'Tracking Competitive Advantage', 'To evaluate which resources and capabilities matter most and how strong the firm is in each.', 'Which resources and capabilities are strategically important, and how strong are we in them?', 'When linking internal capabilities to competitive advantage.', 'Avoid long undifferentiated lists; avoid confusing resources with outcomes.', 'Inventory of resources and capabilities; assessment of their strategic importance.', 'Matrix highlighting priority strengths and weaknesses.', 'Executives identify which capabilities deserve protection or investment.', 'Capability assessment to inform strategic focus and investment priorities.', 'Separate “importance” from “strength” explicitly during discussion.')
INSERT INTO frameworks (idx, slug, name, section, purpose, key_questions, when_to_use, when_not_to_use, inputs_required, outputs, executive_example, consultant_use_case, facilitation_tips) VALUES
  (29, 'the-value-chain-porter', 'The Value Chain (Porter)', 'Tracking Competitive Advantage', 'To analyse how value is created and costs are incurred across activities in the firm.', 'Where do we create value, and where do we incur costs?', 'When examining sources of cost advantage or differentiation.', 'Avoid excessive detail; avoid ignoring linkages between activities.', 'Activity-level cost and process information.', 'Value chain diagram highlighting key activities.', 'Leadership discusses which activities are core to advantage.', 'Activity-based analysis to identify improvement or outsourcing opportunities.', 'Focus discussion on activities that drive differentiation or cost.')
INSERT INTO frameworks (idx, slug, name, section, purpose, key_questions, when_to_use, when_not_to_use, inputs_required, outputs, executive_example, consultant_use_case, facilitation_tips) VALUES
  (30, 'the-product-market-matrix-ansoff', 'The Product/Market Matrix (Ansoff)', 'Tracking Competitive Advantage', 'To explore growth options by combining products and markets.', 'How can we grow through products and markets?', 'When considering growth directions and strategic options.', 'Avoid treating all options as equal risk; avoid using without market insight.', 'Current products and markets; potential new products or markets.', 'Matrix outlining growth options.', 'Executives compare growth paths such as market penetration or diversification.', 'Structuring growth discussions around product–market choices.', 'Discuss risk explicitly across the four quadrants.')
INSERT INTO frameworks (idx, slug, name, section, purpose, key_questions, when_to_use, when_not_to_use, inputs_required, outputs, executive_example, consultant_use_case, facilitation_tips) VALUES
  (31, 'three-generic-strategies-porter-and-the-fatal-bias-goddard', 'Three Generic Strategies (Porter) and the Fatal Bias (Goddard)', 'Bridging the Gap: Business Strategy', 'To define competitive positioning through cost leadership, differentiation, or focus, and to warn against being “stuck in the middle.”', 'How will we compete to achieve competitive advantage?', 'When choosing a clear competitive positioning.', 'Avoid mixing incompatible strategies; avoid unclear positioning.', 'Industry analysis; competitive position assessment.', 'Defined competitive strategy choice.', 'Leadership commits to a clear basis of competition.', 'Positioning diagnosis and strategic choice articulation.', 'Force explicit choice and trade-offs.')
INSERT INTO frameworks (idx, slug, name, section, purpose, key_questions, when_to_use, when_not_to_use, inputs_required, outputs, executive_example, consultant_use_case, facilitation_tips) VALUES
  (32, 'the-experience-curve-bcg', 'The Experience Curve (BCG)', 'Bridging the Gap: Business Strategy', 'To assess cost reduction potential from cumulative production experience.', 'How do costs decline as volume increases?', 'When scale and learning materially affect costs.', 'Avoid assuming experience effects are automatic; avoid ignoring limits.', 'Historical cost and volume data.', 'Experience curve analysis showing cost trends.', 'Executives assess benefits of growth or consolidation.', 'Cost trajectory analysis to support scale strategies.', 'Visualise cost decline versus cumulative output.')
INSERT INTO frameworks (idx, slug, name, section, purpose, key_questions, when_to_use, when_not_to_use, inputs_required, outputs, executive_example, consultant_use_case, facilitation_tips) VALUES
  (33, 'strategic-repositioning-and-shaping-profit-growth-options', 'Strategic Repositioning and Shaping Profit Growth Options', 'Bridging the Gap: Business Strategy', 'To explore ways to reposition the business to improve profit growth.', 'How can we reshape our position to improve profitability?', 'When current positioning limits profit growth.', 'Avoid cosmetic repositioning; avoid ignoring competitive response.', 'Market, customer, and profitability analysis.', 'Identified repositioning options.', 'Leadership considers alternative positioning moves.', 'Option generation for repositioning strategies.', 'Anchor repositioning ideas in profit logic.')
INSERT INTO frameworks (idx, slug, name, section, purpose, key_questions, when_to_use, when_not_to_use, inputs_required, outputs, executive_example, consultant_use_case, facilitation_tips) VALUES
  (34, 'making-the-strategic-investment-decision', 'Making the Strategic Investment Decision', 'Bridging the Gap: Business Strategy', 'To evaluate and prioritise strategic investments.', 'Which strategic investments should we make?', 'When committing resources to strategic initiatives.', 'Avoid optimism bias; avoid ignoring risk and timing.', 'Investment proposals; financial and strategic criteria.', 'Investment decisions with rationale.', 'Board approves or rejects major strategic investments.', 'Investment appraisal supporting strategic choices.', 'Separate strategic logic from financial returns.')
INSERT INTO frameworks (idx, slug, name, section, purpose, key_questions, when_to_use, when_not_to_use, inputs_required, outputs, executive_example, consultant_use_case, facilitation_tips) VALUES
  (35, 'blue-ocean-strategy-kim-and-mauborgne', 'Blue Ocean Strategy (Kim and Mauborgne)', 'Bridging the Gap: Business Strategy', 'To create uncontested market space by redefining industry boundaries.', 'Where can we compete without head-to-head rivalry?', 'When seeking growth beyond existing competitive arenas.', 'Avoid ignoring execution difficulty; avoid underestimating imitation.', 'Industry value curves; customer insights.', 'Blue ocean opportunities and value curves.', 'Executives endorse pursuit of uncontested markets.', 'Market redefinition and value innovation analysis.', 'Use value curves to structure discussion.')
INSERT INTO frameworks (idx, slug, name, section, purpose, key_questions, when_to_use, when_not_to_use, inputs_required, outputs, executive_example, consultant_use_case, facilitation_tips) VALUES
  (36, 'fast-second-markides', 'Fast Second (Markides)', 'Bridging the Gap: Business Strategy', 'To compete effectively by entering after pioneers and learning from them.', 'When is it better to be a fast follower than a first mover?', 'When pioneers face high uncertainty or cost.', 'Avoid late entry without differentiation; avoid copying blindly.', 'Competitor and market entry analysis.', 'Fast-second entry strategy.', 'Leadership chooses to follow rather than lead innovation.', 'Entry-timing analysis and strategy design.', 'Contrast risks of first versus second movers.')
INSERT INTO frameworks (idx, slug, name, section, purpose, key_questions, when_to_use, when_not_to_use, inputs_required, outputs, executive_example, consultant_use_case, facilitation_tips) VALUES
  (37, 'beating-the-commodity-trap-d-aveni', 'Beating the Commodity Trap (d’Aveni)', 'Bridging the Gap: Business Strategy', 'To escape price-based competition by differentiating offerings.', 'How can we avoid competing purely on price?', 'When margins are eroding due to commoditisation.', 'Avoid superficial differentiation; avoid ignoring customer value.', 'Pricing data; competitor offerings; customer needs.', 'Differentiation paths to restore pricing power.', 'Executives approve moves to reduce price pressure.', 'Analysis of commoditisation risks and responses.', 'Push teams to define tangible sources of differentiation.')
INSERT INTO frameworks (idx, slug, name, section, purpose, key_questions, when_to_use, when_not_to_use, inputs_required, outputs, executive_example, consultant_use_case, facilitation_tips) VALUES
  (38, 'discovery-driven-growth-mcgrath', 'Discovery-Driven Growth (McGrath)', 'Bridging the Gap: Business Strategy', 'To manage uncertainty in growth initiatives through staged learning.', 'How do we grow while managing uncertainty and risk?', 'When pursuing uncertain growth opportunities.', 'Avoid rigid planning; avoid ignoring learning milestones.', 'Growth hypotheses; assumptions; staged metrics.', 'Learning milestones and revised plans.', 'Leadership approves staged investment in growth initiatives.', 'Growth initiative design with learning checkpoints.', 'Make assumptions explicit and testable.')
